            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x4A609D05F0B95769ULL;
            aOrbiterF = (((aOrbiterF ^ aOrbiterD) ^ 0xB57632D5A628E82FULL) ^ aSeedOrbiterUpdateSaltE[((aIndex + 5U)) & S_SALT1]) ^ aNonceWordP;
