            aOrbiterJ = ((aWandererB + RotL64(aIngress, 5U)) + 0xBA7DC5215B248DFAULL) + aTwistOrbiterAssignSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterF = (aWandererC + RotL64(aCross, 57U)) + 0x0D08290B9C9F32A3ULL;
