            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xBA6BAB37A81B29C1ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0xE282F09AB2F0D69DULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xD78C86349647F06DULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xF919F1B8B5F4AB3CULL;
