            aOrbiterH = RotL64((aOrbiterH * 0x6C5DD2C506261A61ULL), 35U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0x34F6250CD18D4412ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x671D306238C7E346ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD3CADB0FD30CE287ULL), 53U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x21D59EB02F049B63ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x1FBA4384D602C613ULL;
