            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xAC597549B69EF499ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x536249E49AAB8882ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1];
