            //
            aIngress = (RotL64(aFireLaneD[((aIndex + 11430U)) & S_BLOCK1], 29U) ^ RotL64(aEarthLaneA[((aIndex + 11781U)) & S_BLOCK1], 44U));
            aIngress ^= RotL64(pSnowLaneB[((aIndex + 15810U)) & S_BLOCK1], 57U);
