            aWandererB = aWandererB ^ (((RotL64(aScatter, 47U) + aOrbiterK) + RotL64(aOrbiterC, 43U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1]);
