            aOrbiterG = (((aWandererA + RotL64(aCross, 50U)) + RotL64(aCarry, 27U)) + 0x8C31E7F4557EEA30ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterD = ((aWandererE + RotL64(aIngress, 5U)) + 0x0A459B77AAE1073AULL) + aTwistOrbiterAssignSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterC = (aWandererJ + RotL64(aScatter, 23U)) + 0xEAB141D733796772ULL;
