            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x268A16C12BBD6D99ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x92B1193B0E2A7F7EULL;
            aOrbiterB = RotL64((aOrbiterB * 0x5639C59F098A53D7ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x9D649AF09C0C9738ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x9A1EF69A5D7A8225ULL;
