            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0x83EDAD51F6BA6A3EULL) + aTwistOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0xC2534BE72E24F2B4ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF3757D95D06FE82DULL), 37U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0xF8AC69A29BF64498ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 21U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0xEEB20717CECE410FULL;
