            aOrbiterH = ((aOrbiterH + aOrbiterG) + 0xBE232EA474C2243AULL) + aTwistOrbiterUpdateSaltF[((aIndex + 10U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x72093798F5282853ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x0D119548C07E56F3ULL), 37U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x2960F6EE31AD5D9EULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x8AA3B884DC3C4D88ULL;
