            //
            aCross = (RotL64(aSoilLaneB[((S_BLOCK1 - aIndex + 27462U)) & S_BLOCK1], 13U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 31818U)) & S_BLOCK1], 56U));
            aCross ^= RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 28440U)) & S_BLOCK1], 23U);
