            //
            aScatter = (RotL64(aIngress, 37U) + RotL64(aCarry, 23U)) ^ (RotL64(aPrevious, 52U) + RotL64(aCross, 11U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterB = (aWandererD + RotL64(aPrevious, 56U)) + 0x406698F0D584EC0CULL;
            aOrbiterH = ((aWandererF + RotL64(aScatter, 13U)) + RotL64(aCarry, 53U)) + 0xA5812C8DF8A75465ULL;
            aOrbiterK = (aWandererC + RotL64(aIngress, 21U)) + 0x258FED9656AA913AULL;
            aOrbiterC = (aWandererE + RotL64(aCross, 19U)) + 0xDDEB11E9E15813DCULL;
            aOrbiterF = ((aWandererG + RotL64(aScatter, 28U)) + 0x764C35DD87DD59C4ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterA = ((aWandererK + RotL64(aCross, 3U)) + RotL64(aCarry, 37U)) + 0xEF1E7F38FC28A4B4ULL;
            aOrbiterI = (aWandererH + RotL64(aPrevious, 37U)) + 0x25C69AEB41A970E8ULL;
            aOrbiterJ = (aWandererI + RotL64(aIngress, 11U)) + 0x363DAF99F1675BC3ULL;
            aOrbiterE = (aWandererJ + RotL64(aCross, 43U)) + 0xDB8D614BD5FA067CULL;
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 51U)) + RotL64(aCarry, 27U)) + 0x4DBB82A1743260B6ULL;
            aOrbiterG = ((aWandererB + RotL64(aIngress, 5U)) + 0xB1BCB94242271DA4ULL) + aTwistOrbiterAssignSaltA[((aIndex + 24U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x27498DA8AEDBB90BULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xCBBF6D561B11B8DFULL;
            aOrbiterK = RotL64((aOrbiterK * 0xCA8F49A8736DF47DULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x01A9C861D9BC5D2BULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0x7619DE5BFB6BBF42ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x4D1AE118BD364A43ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x75FD3190A6A3DEC7ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0xB32593A71A7825E8ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xF6A18228E80D88EDULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x60C56A4DB7EAC30BULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x482D82FDA3708276ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xEADC6C1421498B65ULL), 27U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xB3CC39D4CE7F71A9ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xC9C5DE502F0D3B12ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x132CD3504C6596AFULL), 23U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x6072066A8EC2DF05ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x2632C14356291257ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x994877E1E2202479ULL), 41U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0xE95872A15FBB6615ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0xEC44AB686415AEB6ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xF06D127F413891E7ULL), 35U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x5E946E661380F77DULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x2A238092F9D2914CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8B41AAA2EB27B02FULL), 3U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x943C49E54A6ED113ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 23U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xBA4F1CD3F888AD99ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE5CFCB4693E30C6FULL), 21U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x05C26747C8164A81ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0x0CDE14BEE5A2EC92ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x80824E80FC8DF213ULL), 11U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0xDCDC83B0505EAD47ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 11U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x5568DD2593F2D9C2ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7E4B0216097C1741ULL), 43U);
