            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterA, 29U));
            aIngress = aIngress + (RotL64(aOrbiterJ, 3U) ^ aOrbiterF);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterC, 14U));
            aIngress = aIngress + RotL64(aOrbiterB, 41U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 29U) + aOrbiterB) + RotL64(aOrbiterA, 27U));
            aWandererH = aWandererH + (((RotL64(aIngress, 51U) + RotL64(aOrbiterH, 35U)) + aOrbiterB) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 15U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 23U) + aOrbiterI) + RotL64(aOrbiterC, 37U));
