            aOrbiterJ = (((aWandererI + RotL64(aPrevious, 11U)) + RotL64(aCarry, 5U)) + 0x46DE866188F27837ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
