            //
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 26U) + RotL64(aOrbiterD, 37U)) + aOrbiterC);
            aWandererE = aWandererE + (((RotL64(aIngress, 43U) + aOrbiterH) + RotL64(aOrbiterB, 40U)) + RotL64(aCarry, 43U));
