            aOrbiterB = ((aWandererF + RotL64(aCross, 11U)) + 0x0780B2A967476471ULL) + aTwistOrbiterAssignSaltA[((aIndex + 14U)) & S_SALT1];
            aOrbiterF = ((aWandererA + RotL64(aIngress, 51U)) + RotL64(aCarry, 39U)) + 0xA703E23E7D09D73BULL;
