            aWandererC = aWandererC ^ ((RotL64(aPrevious, 39U) + aOrbiterG) + RotL64(aOrbiterF, 58U));
            aWandererG = aWandererG + (((RotL64(aScatter, 11U) + RotL64(aOrbiterA, 19U)) + aOrbiterE) + RotL64(aCarry, 51U));
