            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 6444U)) & W_KEY1], 19U) ^ RotL64(aLightningLaneC[((S_BLOCK1 - aIndex + 423U)) & S_BLOCK1], 28U));
