            aOrbiterB = (aWandererI + RotL64(aIngress, 43U)) + 0xBE2E5EA275625EB3ULL;
            aOrbiterG = (((aWandererH + RotL64(aCross, 19U)) + RotL64(aCarry, 57U)) + 0x40E55FAFE7F0C162ULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 25U)) & S_SALT1];
            aOrbiterJ = (aWandererD + RotL64(aPrevious, 27U)) + 0x6721AEF2234BE468ULL;
