            aOrbiterD = (((aWandererA + RotL64(aIngress, 57U)) + RotL64(aCarry, 41U)) + 0xDD70173AC4A1596CULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 9U)) & S_SALT1];
