            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0xE492B81CE64B885EULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xF359175AB3410ADDULL;
