            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x5F6ACA171358410FULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0x7EC5EEF33DAED45EULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 5U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xE63B3336BF06AD91ULL), 5U);
