            aIngress = (RotL64(aShadowLaneA[((aIndex + 9571U)) & S_BLOCK1], 54U) ^ RotL64(aPoisonLaneC[((aIndex + 16118U)) & S_BLOCK1], 23U));
            aIngress ^= (RotL64(aWaterLaneC[((aIndex + 9557U)) & S_BLOCK1], 41U) ^ RotL64(aSoilLaneD[((aIndex + 15251U)) & S_BLOCK1], 11U));
            aIngress = TwistMix64::DiffuseA(aIngress);
            //
            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 9166U)) & S_BLOCK1], 47U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 10918U)) & S_BLOCK1], 39U));
            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 13928U)) & W_KEY1], 26U) ^ RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 10150U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 21U) ^ RotL64(aCross, 35U)) + (RotL64(aCarry, 52U) ^ RotL64(aPrevious, 3U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterK = (aWandererB + RotL64(aIngress, 19U)) + 0xAC566E842941491CULL;
            aOrbiterJ = ((aWandererI + RotL64(aScatter, 3U)) + RotL64(aCarry, 43U)) + 0x19991A3E58187AEDULL;
            aOrbiterC = (aWandererE + RotL64(aPrevious, 27U)) + 0x4BB7810C92687750ULL;
            aOrbiterE = (aWandererC + RotL64(aCross, 39U)) + 0xA9EBED251032943BULL;
            aOrbiterG = ((aWandererG + RotL64(aIngress, 11U)) + RotL64(aCarry, 13U)) + 0x533B39506BFB75ADULL;
            aOrbiterI = ((aWandererA + RotL64(aCross, 58U)) + 0x5E7B8223C4E909D1ULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterD = (((aWandererJ + RotL64(aPrevious, 51U)) + RotL64(aCarry, 29U)) + 0x6D962A8C542F6EEFULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 12U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x3F58138CC68AED0EULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0xCAAB20A1891E8271ULL) ^ aKeyRotateOrbiterUpdateSaltC[((aIndex + 22U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x58715728E96BF175ULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x17571346F0F7B50CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x42E9935289581B2CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD28393CB33158A0BULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x8C9F8FB2AD62A3B9ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x5E77E7DC493DBDBBULL;
            aOrbiterD = RotL64((aOrbiterD * 0xDA0860A688CB5847ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xD4F7D1326D4E49DCULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0x8BC56522CC603B34ULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x05F7A431EE41DAB5ULL), 3U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x08E2D9DBF26696CBULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x032896E832F583EDULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6D1BB02C302F637BULL), 11U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterK) + 0xD4634DEA8B1388FEULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 6U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x81E505C6B1386753ULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xC42DBFB8651BA5A7ULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x5916215226BDCC2BULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x899C322FA891E042ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xF2AF1D12ECAA584BULL), 35U);
            //
            aIngress = RotL64(aOrbiterJ, 27U) ^ aOrbiterC;
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterE, 57U));
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterG, 21U));
            aIngress = aIngress + RotL64(aOrbiterD, 3U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererE = aWandererE + ((((RotL64(aPrevious, 57U) + RotL64(aOrbiterC, 53U)) + aOrbiterD) + RotL64(aCarry, 23U)) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 8U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 37U) + RotL64(aOrbiterC, 13U)) + aOrbiterG);
            aWandererA = aWandererA + (((RotL64(aCross, 3U) + RotL64(aOrbiterC, 35U)) + aOrbiterK) + RotL64(aCarry, 57U));
            aWandererC = aWandererC ^ ((RotL64(aIngress, 27U) + RotL64(aOrbiterJ, 5U)) + aOrbiterE);
            aWandererI = aWandererI + (((RotL64(aCross, 50U) + aOrbiterJ) + RotL64(aOrbiterD, 43U)) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 11U) + aOrbiterJ) + RotL64(aOrbiterI, 20U));
            aWandererG = aWandererG + ((RotL64(aScatter, 19U) + RotL64(aOrbiterC, 29U)) + aOrbiterI);
