            //
            aWandererG = aWandererG ^ (((RotL64(aScatter, 19U) + aOrbiterB) + RotL64(aOrbiterH, 22U)) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 22U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aIngress, 51U) + aOrbiterF) + RotL64(aOrbiterG, 29U));
            aWandererC = aWandererC ^ ((RotL64(aPrevious, 60U) + aOrbiterC) + RotL64(aOrbiterA, 37U));
