            aWandererF = aWandererF ^ ((RotL64(aPrevious, 53U) + RotL64(aOrbiterG, 47U)) + aOrbiterD);
            aWandererK = aWandererK + (((RotL64(aIngress, 11U) + aOrbiterG) + RotL64(aOrbiterE, 43U)) + RotL64(aCarry, 27U));
