            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCross, 5U) + RotL64(aPrevious, 23U)) + (RotL64(aIngress, 54U) ^ RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterH = (aWandererF + RotL64(aIngress, 52U)) + 0x4FA0D90E747994E2ULL;
            aOrbiterI = ((aWandererJ + RotL64(aPrevious, 57U)) + 0x4BD70564559E7CD0ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterG = ((aWandererI + RotL64(aScatter, 39U)) + RotL64(aCarry, 51U)) + 0xC4D66FB07B7BF03AULL;
            aOrbiterC = (aWandererD + RotL64(aCross, 27U)) + 0xEF2F7E5CED4AAE19ULL;
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 35U)) + RotL64(aCarry, 23U)) + 0x358972423AB30AEBULL;
            aOrbiterE = ((aWandererH + RotL64(aCross, 19U)) + RotL64(aCarry, 13U)) + 0x527C1A106A846F75ULL;
            aOrbiterK = (aWandererK + RotL64(aIngress, 13U)) + 0x1DA45476F0CA57C7ULL;
            aOrbiterB = (aWandererA + RotL64(aScatter, 41U)) + 0xF89A8BE3EF2237F6ULL;
            aOrbiterF = (aWandererC + RotL64(aIngress, 6U)) + 0xA1E054996614F06BULL;
            aOrbiterD = (aWandererG + RotL64(aPrevious, 47U)) + 0xA93366DBA7B56CB7ULL;
            aOrbiterJ = ((aWandererE + RotL64(aCross, 11U)) + 0xBEEBCCD08A55E705ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 26U)) & S_SALT1];
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xEEC328EAB2613265ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x85AEB355B54CFEEBULL;
            aOrbiterG = RotL64((aOrbiterG * 0xB0DF843A88B62F63ULL), 47U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xDB92E89609610EECULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x9A24A0AA05C6C8DFULL;
            aOrbiterA = RotL64((aOrbiterA * 0x3AB50D24F5CC0F81ULL), 53U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0xED6DD666B6DF224FULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0xDF0AED59CA869EE5ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 21U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xC1197A8A9C84E7B9ULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x67A9B10E7E15E8F5ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0xF1BF862ED607DC5EULL;
            aOrbiterF = RotL64((aOrbiterF * 0x67AACE3E85AD4579ULL), 35U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xE06BB41218345393ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x0C114366B5561ECAULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCBE23AFD0B6EA21DULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xB654609872C850F0ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterF) ^ 0x76C80BC668AAA23DULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x8CD0B6CD4769C5C1ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x809F949C47099B96ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x3E7B2CE744C34764ULL) ^ aKeyRotateOrbiterUpdateSaltC[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x412DD97F56CB7D41ULL), 5U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x99CBD4777ABF098FULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x1F917058AE11965FULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8A782AB40D479B8FULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xC72850837648552FULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x8D9ECE9CB676A144ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x1ECE3A7C3BD01AF3ULL), 23U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x3E5D6BA25ADEAC8BULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x3D7013AAFD504FCDULL;
