            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xAD2EDAA9F33979D3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0x89C7C418B382ED7AULL;
            aOrbiterK = RotL64((aOrbiterK * 0x7362170DE196C721ULL), 27U);
