    std::uint8_t *aShadowLaneD = pWorkSpace->mShadowLaneD;
    std::uint8_t *aAetherLaneA = pWorkSpace->mAetherLaneA;
    std::uint8_t *aAetherLaneB = pWorkSpace->mAetherLaneB;
    std::uint8_t *aAetherLaneC = pWorkSpace->mAetherLaneC;
    std::uint8_t *aAetherLaneD = pWorkSpace->mAetherLaneD;
    std::uint8_t *aVaporLaneA = pWorkSpace->mVaporLaneA;
    std::uint8_t *aVaporLaneB = pWorkSpace->mVaporLaneB;
    std::uint8_t *aVaporLaneC = pWorkSpace->mVaporLaneC;
    std::uint8_t *aVaporLaneD = pWorkSpace->mVaporLaneD;
    std::uint8_t *aKeyRowReadA = &(pWorkSpace->mKeyBoxA[H_KEY - 1][0]);
    std::uint8_t *aKeyRowReadB = &(pWorkSpace->mKeyBoxB[H_KEY - 1][0]);
    std::uint64_t *aKeyRotateOrbiterAssignSaltA = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterAssign.mSaltA;
    std::uint64_t *aKeyRotateOrbiterAssignSaltB = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterAssign.mSaltB;
    std::uint64_t *aKeyRotateOrbiterAssignSaltC = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterAssign.mSaltC;
    std::uint64_t *aKeyRotateOrbiterAssignSaltD = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterAssign.mSaltD;
