            //
            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0x6B846A1B6872FE93ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xF66EED82DF23C39AULL;
