            aOrbiterC = (((aWandererD + RotL64(aPrevious, 23U)) + RotL64(aCarry, 51U)) + 0x340A2A5F6E2D8EBAULL) + aKeySpawnOrbiterAssignSaltF[((aIndex + 21U)) & S_SALT1];
