            aOrbiterD = ((aWandererI + RotL64(aIngress, 29U)) + 0xF642B952E1F74CBCULL) + aKeySpawnOrbiterAssignSaltE[(((31U - aIndex) + 8U)) & S_SALT1];
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0xEA494AEA2974AF56ULL) + aKeySpawnOrbiterUpdateSaltC[((aIndex + 20U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x8F14ED177985C69DULL;
