            //
            aWandererK = aWandererK + ((((RotL64(aScatter, 20U) + aOrbiterG) + RotL64(aOrbiterE, 53U)) + RotL64(aCarry, 5U)) + aKeySpawnWandererUpdateSaltA[(((31U - aIndex) + 16U)) & S_SALT1]);
