            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0xB8C8B77712028492ULL) + aKeySpawnOrbiterUpdateSaltA[((aIndex + 8U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x65359CCB2C7DB8BEULL;
