            aOrbiterI = RotL64((aOrbiterI * 0xF8177957140661B9ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0x2AF3620A2DE25C12ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x23DE197540F8D82DULL;
