            aOrbiterC = (((aWandererG + RotL64(aScatter, 57U)) + RotL64(aCarry, 47U)) + 0x476567C4793BB0AAULL) + aKeySpawnOrbiterAssignSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
