            aOrbiterG = (aWandererH + RotL64(aCross, 34U)) + 0xE234BBDEFE22F1B6ULL;
            aOrbiterF = (aWandererK + RotL64(aScatter, 13U)) + 0x72E10B7A44087516ULL;
