            aOrbiterK = (((aWandererE + RotL64(aPrevious, 39U)) + RotL64(aCarry, 35U)) + 0x3DC0928C1C920B9AULL) + aKeySpawnOrbiterAssignSaltA[((aIndex + 9U)) & S_SALT1];
