            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x6967F0E69555130CULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0xD6835B6A6D2660A1ULL) ^ aKeySpawnOrbiterUpdateSaltB[((aIndex + 29U)) & S_SALT1];
